/**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/developers/block-api/#registering-a-block
 */
import { registerBlockType } from '@wordpress/blocks';

const { Fragment, InnerBlocks } = wp.editor;

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/developers/block-api/#registering-a-block
 */
registerBlockType( 'sting/grid-campaign', {
	title: 'Grid Campaign',
	description: 'Example block written with ESNext standard and JSX support – build step required.',
	category: 'common',
	icon: 'grid-view',
	attributes: {
		'title': {
			type: 'string',
			default: ''
		},
	},
	supports: {
		// Removes support for an HTML mode.
		html: false,
	},
	edit( { attributes, setAttributes } ) {
		const { title } = attributes;
		const ALLOWED_BLOCKS = [ 'sting/campaign' ];
		return (
			<div className="sting-grid">
				<InnerBlocks
					allowedBlocks={ALLOWED_BLOCKS}
				/>
			</div>
		);
	},
	save( { attributes } ) {
		const { title } = attributes;
		return (
			<div className="Campaign" data-controller="campaign">
				<script type="text/template" data-target="campaign.indicatorTemplate">
					<li className="Campaign-itemIndicator" data-target="campaign.indicator"></li>
				</script>
				<ul className="Campaign-list Grid Grid--noWrap Grid--padded Grid--compensatePadded" data-target="campaign.list">
					<InnerBlocks.Content />
				</ul>
				<div className="Campaign-nav">
					<button type="button" className="Campaign-navButton Campaign-navButton--previous" data-target="campaign.previous">
						<span className="Campaign-navButtonIcon Icon Icon--chevronLargeLeft"></span>
						<span className="Campaign-navButtonLabel">Föregående</span>
					</button>
					<button type="button" className="Campaign-navButton Campaign-navButton--next" data-target="campaign.next">
						<span className="Campaign-navButtonIcon Icon Icon--chevronLargeRight"></span>
						<span className="Campaign-navButtonLabel">Nästa</span>
					</button>
					<ul className="Campaign-itemIndicators" data-target="campaign.indicators" aria-hidden="true"></ul>
				</div>
			</div>
		);
	},
} );
